export type HeaderCommand =
  | (HeaderCommandBase & { kind: Exclude<HeaderCommandKind, "navigate_workspace"> })
  | (HeaderCommandBase & { kind: "navigate_workspace"; section: NativeSection });

export type SidebarCommand =
  | (SidebarCommandBase & { kind: "navigate"; section: NativeSection })
  | (SidebarCommandBase & { kind: "open_session"; sessionId: string; section: NativeSection })
  | (SidebarCommandBase & { kind: "open_profile_canvas"; canvas: ProfileCanvas })
  | (SidebarCommandBase & { kind: "archive_session"; sessionId: string })
  | (SidebarCommandBase & { kind: "activate_control"; label: string })
  | (SidebarCommandBase & { kind: "switch_sessions_mode"; mode: SessionsMenuMode })
  | (SidebarCommandBase & { kind: "toggle_profile_menu" })
  | (SidebarCommandBase & { kind: "set_active_drawer"; drawer: string })
  | (SidebarCommandBase & { kind: "hide_tool"; toolId: string })
  | (SidebarCommandBase & { kind: "restore_tool"; toolId: string })
  | (SidebarCommandBase & { kind: "pin_session"; sessionId: string; label: string; section: NativeSection })
  | (SidebarCommandBase & { kind: "confirm_archive" })
  | (SidebarCommandBase & { kind: "cancel_archive" });

export type PanelsChatBottomCommand = PanelsChatBottomCommandBase & {
  kind: PanelsChatBottomCommandKind;
  value?: string;
  provider?: "openai" | "anthropic" | "openrouter";
  direction?: number;
  attachmentIds?: string[];
  filePaths?: string[];
  moduleId?: string;
  parallelSessionIndex?: number;
  parallelDrafts?: ParallelChatDraft[];
  internalPrompt?: boolean;
  replaceAssistantMessageId?: string;
  userFirstName?: string;
  agentFirstName?: string;
};

export type CanvasSurfacesCommand = CanvasSurfacesCommandBase & {
  kind: CanvasSurfacesCommandKind;
  target?: string;
  value?: string;
  section?: NativeSection;
  canvas?: ProfileCanvas;
};

export type RightPanelCommand = RightPanelCommandBase & {
  kind: RightPanelCommandKind;
  target?: string;
  value?: string;
};
